package com.bankpli.javabank.account;
import java.math.BigDecimal;import java.net.URI;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/accounts") public class AccountController {private final AccountService service;private final MortgageCalculator mortgage;private final InterestService interest;public AccountController(AccountService s,MortgageCalculator m,InterestService i){service=s;mortgage=m;interest=i;}@PostMapping public ResponseEntity<Account> create(@RequestBody AccountRequest r){Account a=service.create(r);return ResponseEntity.created(URI.create("/api/accounts/"+a.getId())).body(a);}@GetMapping("/{id}") public Account get(@PathVariable long id){return service.get(id);}@PostMapping("/{id}/deactivate")public Account deactivate(@PathVariable long id){return service.deactivate(id);}@PostMapping("/{id}/holders/{customerId}")public Account add(@PathVariable long id,@PathVariable long customerId){return service.addHolder(id,customerId);}@DeleteMapping("/{id}/holders/{customerId}")public Account remove(@PathVariable long id,@PathVariable long customerId){return service.removeHolder(id,customerId);}@GetMapping("/mortgage")public Map<String,Object> mortgage(@RequestParam BigDecimal principal,@RequestParam BigDecimal annualRate,@RequestParam int months){return Map.of("payment",mortgage.payment(principal,annualRate,months),"schedule",mortgage.schedule(principal,annualRate,months));}@GetMapping("/interest")public Map<String,BigDecimal> interest(@RequestParam BigDecimal balance,@RequestParam BigDecimal annualRate,@RequestParam long days){return Map.of("accrued",interest.accrue(balance,annualRate,days));}}
